"use client";

import { useCallback, useEffect, useId, useState } from "react";
import { motion } from "framer-motion";
import { ArrowUpRight, Link2Off, RotateCw, X } from "lucide-react";
import { ease } from "@/components/bjork-ui/_core/motion";
import {
  CardButton,
  CardFrame,
  Skeleton,
  focusRing,
  useCardTheme,
  useReducedMotionSafe,
  type CardTheme,
} from "@/components/bjork-ui/cards/card-kit";
import { cn } from "@/lib/utils";

export interface LinkMeta {
  title: string;
  description?: string;
  siteName?: string;
  /** Open Graph image URL. Without one the card draws a cover from `themeColor`. */
  image?: string;
  imageAlt?: string;
  favicon?: string;
  /** ISO date. */
  publishedAt?: string;
  author?: string;
  readingMinutes?: number;
  themeColor?: string;
}

export type LinkPreviewLayout = "large" | "compact";

export interface LinkPreviewCardProps {
  url?: string;
  /** Known metadata. Skips `resolve`. */
  meta?: LinkMeta;
  /** Fetches metadata for `url` (your unfurl endpoint). Rejects show the fallback. */
  resolve?: (url: string) => Promise<LinkMeta>;
  layout?: LinkPreviewLayout;
  /** Shows a remove button, e.g. in a composer. */
  onDismiss?: () => void;
  /** Open in a new tab. Default true. */
  external?: boolean;
  locale?: string;
  theme?: CardTheme;
  className?: string;
}

export const LINK_PREVIEW_SAMPLE = {
  url: "https://fieldnotes.studio/essays/quiet-interfaces",
  meta: {
    title: "Quiet interfaces: designing software that gets out of the way",
    description:
      "Notes from three years of shipping tools for people who would rather be doing something else. On defaults, restraint and the craft of the boring parts.",
    siteName: "Field Notes",
    author: "Ines Albrecht",
    publishedAt: "2026-09-14",
    readingMinutes: 9,
    themeColor: "#ec5c13",
  } satisfies LinkMeta,
};

type Load = { state: "idle" | "loading" | "ready" | "error"; meta?: LinkMeta };

function hostOf(url: string) {
  try {
    return new URL(url).hostname.replace(/^www\./, "");
  } catch {
    return url;
  }
}

/**
 * An Open Graph unfurl for chat, docs and composers. Loads with a matching skeleton, falls back to a
 * plain link when the page can't be read, and stays one link so it reads cleanly with a screen reader.
 */
export function LinkPreviewCard({
  url = LINK_PREVIEW_SAMPLE.url,
  meta,
  resolve,
  layout = "large",
  onDismiss,
  external = true,
  locale = "en-US",
  theme = "auto",
  className,
}: LinkPreviewCardProps) {
  const { style } = useCardTheme(theme);
  const reduce = useReducedMotionSafe();
  const titleId = useId();
  const host = hostOf(url);

  const [load, setLoad] = useState<Load>(() =>
    meta ? { state: "ready", meta } : resolve ? { state: "loading" } : { state: "ready", meta: LINK_PREVIEW_SAMPLE.meta },
  );
  const [attempt, setAttempt] = useState(0);
  const [imageFailed, setImageFailed] = useState(false);

  useEffect(() => {
    if (meta || !resolve) return;
    let live = true;
    resolve(url).then(
      (m) => live && setLoad({ state: "ready", meta: m }),
      () => live && setLoad({ state: "error" }),
    );
    return () => {
      live = false;
    };
  }, [url, meta, resolve, attempt]);

  const retry = useCallback(() => {
    setLoad({ state: "loading" });
    setImageFailed(false);
    setAttempt((a) => a + 1);
  }, []);

  const data = meta ?? load.meta;
  const state = meta ? "ready" : load.state;
  const compact = layout === "compact";
  const linkProps = external ? { target: "_blank", rel: "noopener noreferrer" } : {};

  const dismiss = onDismiss && (
    <button
      type="button"
      onClick={onDismiss}
      aria-label="Remove link preview"
      className={cn(
        "absolute right-2 top-2 z-20 grid size-7 cursor-pointer place-items-center rounded-full bg-black/45 text-white backdrop-blur-sm transition-[background-color,transform] hover:bg-black/65 active:scale-[0.92] motion-reduce:transition-none",
        focusRing,
      )}
    >
      <X aria-hidden="true" className="size-3.5" />
    </button>
  );

  if (state === "loading" || state === "idle") {
    return (
      <CardFrame as="div" aria-busy="true" aria-label={`Loading preview for ${host}`} className={className} style={style} maxWidth={compact ? 460 : 420}>
        {dismiss}
        <div className={cn(compact ? "flex gap-3 p-3" : "")}>
          <Skeleton className={cn(compact ? "size-[72px] shrink-0 rounded-[10px]" : "aspect-[1.91] w-full rounded-none")} />
          <div className={cn("flex-1 space-y-2", compact ? "py-1" : "p-4")}>
            <Skeleton className="h-3 w-24" />
            <Skeleton className="h-4 w-[85%]" />
            {!compact && <Skeleton className="h-3 w-full" />}
            <Skeleton className="h-3 w-2/3" />
          </div>
        </div>
      </CardFrame>
    );
  }

  if (state === "error" || !data) {
    return (
      <CardFrame as="article" aria-labelledby={titleId} className={cn("group", className)} style={style} maxWidth={460}>
        {dismiss}
        <div className="flex items-center gap-3 p-3 pr-4">
          <span className="grid size-10 shrink-0 place-items-center rounded-[10px] bg-[color:var(--bjork-card-raised)] text-[color:var(--bjork-text-muted)] ring-1 ring-[color:var(--bjork-border)]">
            <Link2Off aria-hidden="true" className="size-4" />
          </span>
          <div className="min-w-0 flex-1">
            <a
              id={titleId}
              href={url}
              {...linkProps}
              className={cn("block truncate rounded-[4px] text-[13px] font-medium leading-5 underline-offset-2 hover:underline", focusRing)}
            >
              {host}
            </a>
            <p className="truncate text-[12px] leading-4 text-[color:var(--bjork-text-muted)]">Preview unavailable · {url.replace(/^https?:\/\//, "")}</p>
          </div>
          {resolve && (
            <CardButton size="sm" variant="ghost" onClick={retry} aria-label="Retry loading preview" icon={<RotateCw aria-hidden="true" className="size-3.5" />} className={onDismiss ? "mr-7" : ""}>
              Retry
            </CardButton>
          )}
        </div>
      </CardFrame>
    );
  }

  const date = data.publishedAt
    ? new Intl.DateTimeFormat(locale, { month: "short", day: "numeric", year: "numeric", timeZone: "UTC" }).format(Date.parse(data.publishedAt))
    : null;
  const metaBits = [data.author, date, data.readingMinutes ? `${data.readingMinutes} min read` : null].filter(Boolean);
  const showImage = data.image && !imageFailed;

  const cover = (
    <div className={cn("relative overflow-hidden bg-[color:var(--bjork-card-raised)]", compact ? "size-[72px] shrink-0 rounded-[10px]" : "aspect-[1.91] w-full")}>
      {showImage ? (
        // eslint-disable-next-line @next/next/no-img-element
        <img
          src={data.image}
          alt={data.imageAlt ?? ""}
          onError={() => setImageFailed(true)}
          className="size-full object-cover transition-transform duration-500 ease-out group-hover:scale-[1.03] motion-reduce:transition-none motion-reduce:group-hover:scale-100"
        />
      ) : (
        <GeneratedCover color={data.themeColor ?? "#ec5c13"} label={data.siteName ?? host} compact={compact} />
      )}
    </div>
  );

  return (
    <CardFrame as="article" aria-labelledby={titleId} className={cn("group transition-[border-color] hover:border-[color:var(--bjork-border-strong)]", className)} style={style} maxWidth={compact ? 460 : 420}>
      {dismiss}
      <motion.div
        initial={reduce ? false : { opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ duration: 0.3, ease: ease.out }}
        className={cn(compact && "flex items-center gap-3 p-3 pr-4")}
      >
        {cover}
        <div className={cn("min-w-0", compact ? "flex-1" : "p-4")}>
          <p className="flex min-w-0 items-center gap-1.5 text-[12px] leading-4 text-[color:var(--bjork-text-muted)]">
            {data.favicon ? (
              // eslint-disable-next-line @next/next/no-img-element
              <img src={data.favicon} alt="" className="size-3.5 shrink-0 rounded-[3px]" />
            ) : (
              <span
                aria-hidden="true"
                className="grid size-3.5 shrink-0 place-items-center rounded-[3px] text-[8px] font-bold text-white"
                style={{ background: data.themeColor ?? "#ec5c13" }}
              >
                {(data.siteName ?? host)[0]}
              </span>
            )}
            <span className="truncate">
              {data.siteName && <span className="text-[color:var(--bjork-text-medium)]">{data.siteName}</span>}
              {data.siteName && " · "}
              {host}
            </span>
          </p>
          <h3 id={titleId} className={cn("mt-1.5 font-semibold tracking-[-0.005em]", compact ? "line-clamp-1 text-[13px] leading-5" : "line-clamp-2 text-[15px] leading-5")}>
            {/* Stretched link: the whole card is one target, the dismiss button stays separate. */}
            <a
              href={url}
              {...linkProps}
              className="rounded-[4px] outline-none after:absolute after:inset-0 after:z-10 after:rounded-[20px] after:content-[''] focus-visible:after:ring-2 focus-visible:after:ring-[color:var(--bjork-accent)] focus-visible:after:ring-inset"
            >
              {data.title}
              {external && <span className="sr-only"> (opens in a new tab)</span>}
            </a>
          </h3>
          {data.description && (
            <p className={cn("mt-1 text-[13px] leading-5 text-[color:var(--bjork-text-medium)]", compact ? "line-clamp-1" : "line-clamp-2")}>
              {data.description}
            </p>
          )}
          {!compact && metaBits.length > 0 && (
            <p className="mt-3 flex items-center justify-between gap-3 text-[12px] leading-4 text-[color:var(--bjork-text-muted)]">
              <span className="truncate">{metaBits.join(" · ")}</span>
              <ArrowUpRight
                aria-hidden="true"
                className="size-4 shrink-0 text-[color:var(--bjork-text-soft)] transition-[transform,color] duration-200 group-hover:-translate-y-0.5 group-hover:translate-x-0.5 group-hover:text-[color:var(--bjork-text)] motion-reduce:transition-none motion-reduce:group-hover:translate-x-0 motion-reduce:group-hover:translate-y-0"
              />
            </p>
          )}
        </div>
      </motion.div>
    </CardFrame>
  );
}

function GeneratedCover({ color, label, compact }: { color: string; label: string; compact: boolean }) {
  return (
    <div
      aria-hidden="true"
      className="absolute inset-0 transition-transform duration-500 ease-out group-hover:scale-[1.03] motion-reduce:transition-none motion-reduce:group-hover:scale-100"
      style={{
        background: `radial-gradient(90% 120% at 85% 110%, color-mix(in oklab, ${color} 85%, white) 0%, ${color} 28%, transparent 60%), radial-gradient(70% 90% at 0% 0%, color-mix(in oklab, ${color} 40%, black) 0%, transparent 70%), linear-gradient(160deg, #1a1a1a, #0c0c0c)`,
      }}
    >
      <div
        className="absolute inset-0 opacity-[0.18]"
        style={{
          backgroundImage: "linear-gradient(rgba(255,255,255,0.5) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,0.5) 1px, transparent 1px)",
          backgroundSize: compact ? "12px 12px" : "28px 28px",
          maskImage: "linear-gradient(to bottom right, black, transparent 70%)",
        }}
      />
      {!compact && (
        <span className="absolute bottom-4 left-4 font-bjork-display text-[28px] font-semibold leading-none tracking-[-0.02em] text-white/90">
          {label}
        </span>
      )}
    </div>
  );
}

// Shared springs, easings and durations. Components import these instead of inventing values.

export const springs = {
  press: { type: "spring", stiffness: 500, damping: 30, mass: 0.6 },
  snappy: { type: "spring", stiffness: 400, damping: 25, mass: 1 },
  standard: { type: "spring", stiffness: 300, damping: 30, mass: 0.8 },
  soft: { type: "spring", stiffness: 200, damping: 25, mass: 1.2 },
  settle: { type: "spring", stiffness: 380, damping: 30, mass: 0.8 },
  blurIn: { type: "spring", stiffness: 400, damping: 28, mass: 0.6 },
} as const;

export const ease = {
  out: [0.23, 1, 0.32, 1],
  inOut: [0.77, 0, 0.175, 1],
  drawer: [0.32, 0.72, 0, 1],
} as const;

export const easeCss = {
  out: "cubic-bezier(0.23,1,0.32,1)",
  inOut: "cubic-bezier(0.77,0,0.175,1)",
  drawer: "cubic-bezier(0.32,0.72,0,1)",
} as const;

export const durations = { press: 140, tooltip: 160, menu: 200, panel: 280 } as const; // ms

// Cubic bezier easing for canvas and rAF code. Returns progress y for input x in [0, 1].
export function cubicBezier(x1: number, y1: number, x2: number, y2: number): (t: number) => number {
  const cx = 3 * x1;
  const bx = 3 * (x2 - x1) - cx;
  const ax = 1 - cx - bx;
  const cy = 3 * y1;
  const by = 3 * (y2 - y1) - cy;
  const ay = 1 - cy - by;
  const sampleX = (s: number) => ((ax * s + bx) * s + cx) * s;
  const sampleY = (s: number) => ((ay * s + by) * s + cy) * s;
  const sampleDX = (s: number) => (3 * ax * s + 2 * bx) * s + cx;

  const solveX = (x: number) => {
    let s = x;
    for (let i = 0; i < 8; i++) {
      const err = sampleX(s) - x;
      if (Math.abs(err) < 1e-6) return s;
      const d = sampleDX(s);
      if (Math.abs(d) < 1e-6) break;
      s -= err / d;
    }
    let lo = 0;
    let hi = 1;
    s = x;
    while (lo < hi) {
      const v = sampleX(s);
      if (Math.abs(v - x) < 1e-6) return s;
      if (x > v) lo = s;
      else hi = s;
      s = (lo + hi) / 2;
      if (hi - lo < 1e-7) break;
    }
    return s;
  };

  return (t: number) => {
    if (t <= 0) return 0;
    if (t >= 1) return 1;
    return sampleY(solveX(t));
  };
}

"use client";

import {
  forwardRef,
  useSyncExternalStore,
  type ButtonHTMLAttributes,
  type CSSProperties,
  type HTMLAttributes,
  type ReactNode,
} from "react";
import { useReducedMotion } from "framer-motion";
import type { BjorkTone } from "@/components/bjork-ui/_core/palette";
import { surfaceVars } from "@/components/bjork-ui/_core/surface";
import { useBjorkTone } from "@/components/bjork-ui/_core/tone";
import { cn } from "@/lib/utils";

/** "auto" follows the site theme (next-themes). "light" and "dark" pin the card. */
export type CardTheme = "light" | "dark" | "auto";

/**
 * Card tokens. They are written onto the card root as the library's `--bjork-*` custom properties,
 * so a pinned theme wins over the page theme, and the status colours the global sheet lacks
 * (success, warning, error) are always defined.
 */
export const CARD_TOKENS = {
  dark: {
    card: "#141414",
    raised: "#1b1b1b",
    inset: "#0d0d0d",
    hover: "#1f1f1f",
    border: "#242424",
    borderStrong: "#363636",
    hair: "rgba(237,237,237,0.08)",
    text: "#ededed",
    textMedium: "rgba(237,237,237,0.74)",
    textMuted: "rgba(237,237,237,0.56)",
    textSoft: "rgba(237,237,237,0.4)",
    textFaint: "rgba(237,237,237,0.22)",
    accent: "#ec5c13",
    accentInk: "#f27a3c",
    accentFill: "#b84a12",
    accentFillHover: "#c95517",
    accentFg: "#fff2ea",
    accentSoft: "rgba(236,92,19,0.13)",
    accentMuted: "rgba(236,92,19,0.26)",
    success: "#4cc38a",
    successSoft: "rgba(76,195,138,0.13)",
    warning: "#f2b544",
    warningSoft: "rgba(242,181,68,0.13)",
    error: "#ff6b5c",
    errorSoft: "rgba(255,107,92,0.13)",
    track: "#262626",
    shadow:
      "inset 0 1px 0 rgba(255,255,255,0.045), 0 1px 0 rgba(0,0,0,0.5), 0 24px 48px -28px rgba(0,0,0,0.9)",
    raisedShadow: "inset 0 1px 0 rgba(255,255,255,0.04)",
  },
  light: {
    card: "#fffcf6",
    raised: "#f7f1e6",
    inset: "#f1eadd",
    hover: "#f3ecdf",
    border: "#ebe2d4",
    borderStrong: "#dbcfbd",
    hair: "rgba(23,23,23,0.07)",
    text: "#171717",
    textMedium: "rgba(23,23,23,0.76)",
    textMuted: "rgba(23,23,23,0.62)",
    textSoft: "rgba(23,23,23,0.46)",
    textFaint: "rgba(23,23,23,0.2)",
    accent: "#ec7d43",
    accentInk: "#a84a19",
    accentFill: "#ec7d43",
    accentFillHover: "#f0935f",
    accentFg: "#3f2112",
    accentSoft: "rgba(236,125,67,0.12)",
    accentMuted: "rgba(236,125,67,0.24)",
    success: "#1b7f4d",
    successSoft: "rgba(31,138,85,0.11)",
    warning: "#966000",
    warningSoft: "rgba(168,107,0,0.11)",
    error: "#c0331d",
    errorSoft: "rgba(200,54,31,0.1)",
    track: "#ebe3d6",
    shadow:
      "inset 0 1px 0 rgba(255,255,255,0.9), 0 1px 2px rgba(66,52,33,0.06), 0 22px 44px -28px rgba(66,52,33,0.26)",
    raisedShadow: "inset 0 1px 0 rgba(255,255,255,0.7)",
  },
} as const;

export type CardTokens = (typeof CARD_TOKENS)[BjorkTone];

export function cardVars(tone: BjorkTone): CSSProperties {
  const t = CARD_TOKENS[tone];
  return {
    colorScheme: tone,
    ...surfaceVars(tone),
    "--bjork-card": t.card,
    "--bjork-card-raised": t.raised,
    "--bjork-card-inset": t.inset,
    "--bjork-card-hover": t.hover,
    "--bjork-border": t.border,
    "--bjork-border-strong": t.borderStrong,
    "--bjork-hair": t.hair,
    "--bjork-text": t.text,
    "--bjork-text-medium": t.textMedium,
    "--bjork-text-muted": t.textMuted,
    "--bjork-text-soft": t.textSoft,
    "--bjork-text-faint": t.textFaint,
    "--bjork-accent": t.accent,
    "--bjork-accent-ink": t.accentInk,
    "--bjork-accent-fill": t.accentFill,
    "--bjork-accent-fill-hover": t.accentFillHover,
    "--bjork-accent-foreground": t.accentFg,
    "--bjork-accent-soft": t.accentSoft,
    "--bjork-accent-muted": t.accentMuted,
    "--bjork-success": t.success,
    "--bjork-success-soft": t.successSoft,
    "--bjork-warning": t.warning,
    "--bjork-warning-soft": t.warningSoft,
    "--bjork-error": t.error,
    "--bjork-error-soft": t.errorSoft,
    "--bjork-track": t.track,
    "--bjork-card-shadow": t.shadow,
    "--bjork-raised-shadow": t.raisedShadow,
    "--bjork-ring-offset": t.card,
  } as CSSProperties;
}

/** Resolves the card tone and the CSS variables for it. */
export function useCardTheme(theme: CardTheme = "auto") {
  const tone = useBjorkTone(theme === "auto" ? undefined : theme);
  return { tone, tokens: CARD_TOKENS[tone], style: cardVars(tone) };
}

const noopSubscribe = () => () => {};

/** True after hydration. The server render and the first client render both see false. */
export function useHydrated() {
  return useSyncExternalStore(
    noopSubscribe,
    () => true,
    () => false,
  );
}

/** Reduced-motion preference, hydration-safe: false until mounted. */
export function useReducedMotionSafe() {
  const hydrated = useHydrated();
  const reduced = useReducedMotion();
  return hydrated && reduced === true;
}

const clockStores = new Map<number, { subscribe: (cb: () => void) => () => void; get: () => number }>();

function clockStore(stepMs: number) {
  let store = clockStores.get(stepMs);
  if (!store) {
    store = {
      subscribe: (cb) => {
        const id = window.setInterval(cb, Math.min(stepMs, 1000));
        return () => window.clearInterval(id);
      },
      get: () => Math.floor(Date.now() / stepMs) * stepMs,
    };
    clockStores.set(stepMs, store);
  }
  return store;
}

/**
 * Wall clock rounded to `stepMs`. A fixed `now` (previews, tests) wins. Returns null during SSR and
 * hydration so server and client text agree; callers render a neutral fallback for that frame.
 */
export function useClock(now: number | undefined, stepMs = 60_000): number | null {
  const store = clockStore(stepMs);
  const live = useSyncExternalStore(store.subscribe, store.get, () => null);
  return now ?? live;
}

export const focusRing =
  "outline-none focus-visible:ring-2 focus-visible:ring-[color:var(--bjork-accent)] focus-visible:ring-offset-2 focus-visible:ring-offset-[color:var(--bjork-ring-offset)]";

export interface CardFrameProps extends HTMLAttributes<HTMLElement> {
  style?: CSSProperties;
  /** Width in px, capped at the container width. Default 420. */
  maxWidth?: number;
  as?: "section" | "article" | "div";
}

/** The shared card surface: tokens, radius, border, shadow and a container query root. */
export const CardFrame = forwardRef<HTMLElement, CardFrameProps>(function CardFrame(
  { as: Tag = "section", maxWidth = 420, className, style, children, ...rest },
  ref,
) {
  return (
    <Tag
      ref={ref as never}
      className={cn(
        "@container relative max-w-full overflow-hidden rounded-[20px] border border-[color:var(--bjork-border-muted)] bg-[color:var(--bjork-card)] font-bjork-alpha text-[color:var(--bjork-text)] shadow-[var(--bjork-shadow-surface)] [font-variant-numeric:tabular-nums]",
        className,
      )}
      // A fixed width capped at the container: fills narrow columns, and keeps its size inside
      // shrink-to-fit parents (flex centring, popovers) where a percentage width would collapse.
      style={{ width: maxWidth, ...style }}
      {...rest}
    >
      {children}
    </Tag>
  );
});

type ButtonVariant = "primary" | "secondary" | "ghost" | "danger";

export interface CardButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: ButtonVariant;
  size?: "sm" | "md";
  icon?: ReactNode;
}

const buttonVariants: Record<ButtonVariant, string> = {
  primary:
    "bg-[color:var(--bjork-accent-fill)] text-[color:var(--bjork-accent-foreground)] hover:bg-[color:var(--bjork-accent-fill-hover)] shadow-[inset_0_1px_0_rgba(255,255,255,0.16)]",
  secondary:
    "border border-[color:var(--bjork-border)] bg-[color:var(--bjork-card-raised)] text-[color:var(--bjork-text)] shadow-[var(--bjork-raised-shadow)] hover:bg-[color:var(--bjork-card-hover)] hover:border-[color:var(--bjork-border-strong)]",
  ghost:
    "text-[color:var(--bjork-text-medium)] hover:bg-[color:var(--bjork-card-hover)] hover:text-[color:var(--bjork-text)]",
  danger:
    "border border-[color:var(--bjork-border)] bg-[color:var(--bjork-error-soft)] text-[color:var(--bjork-error)] hover:border-[color:var(--bjork-error)]",
};

export const CardButton = forwardRef<HTMLButtonElement, CardButtonProps>(function CardButton(
  { variant = "secondary", size = "md", icon, className, children, type = "button", ...rest },
  ref,
) {
  return (
    <button
      ref={ref}
      type={type}
      className={cn(
